// Everything else people keep in and around a house: the 300-odd everyday things beyond the first
// catalogue (beds at every mattress size, couches and chairs of every kind, fireplaces and stoves,
// dishes and small appliances, stereos and speakers, vacuums, cars and motorcycles, gym gear, garden
// and patio, kids' rooms). Each has its real US size, weight, mount and a look built from simple
// shapes (x right as seen from the front, y up from its bottom, z toward its front, mm from the
// middle of its footprint), stretched to the size it is placed at. HOME_SECTIONS files every kind
// under a room for the tray (lib/plan/tray.ts).
import type { ObjectSpec, Part } from "./catalog";

const b = (x: number, y: number, z: number, w: number, d: number, h: number, color?: string): Part => ({ shape: "box", x, y, z, w, d, h, color });
const c = (x: number, y: number, z: number, w: number, d: number, h: number, color?: string): Part => ({ shape: "cylinder", x, y, z, w, d, h, color });
const s = (x: number, y: number, z: number, w: number, d: number, h: number, color?: string): Part => ({ shape: "sphere", x, y, z, w, d, h, color });
/** inches to mm */
const n = (inch: number) => Math.round(inch * 25.4);

// colours. Woods get grain, fabrics a weave, metals and glass shine (see LOOK_OF and shapes3d.ts)
const OAK = "#b08a5e", WOOD = "#a07850", WALNUT = "#6e4f37", DARK = "#8a6a48", PINE = "#c49a66", PAINT = "#e4dccb";
const WHITE = "#f4efe6", PORC = "#f7f5f0", BLACK = "#232426", INK = "#1b1a17", GREY = "#7d8187", CONCRETE = "#9c9a94";
const STEEL = "#b9bec4", CHROME = "#c9ced3", BRASS = "#b8954a", IRON = "#3a3b3e", COPPER = "#b06a43", ALU = "#a7acb1";
const GLASS = "#cfe6ee", MIRROR = "#8fb8c9", TINT = "#2e3a44", SCREEN = "#24384f", GLOW = "#ffe7a8", FLAME = "#ff9a3c";
const LINEN = "#e9e3d6", FABRIC = "#6f7486", CUSHION = "#7d8296", SAGE = "#8a9a7b", NAVY = "#34405a", RUST = "#a5583a",
  CREAM = "#ddd3bf", CHARCOAL = "#4a4d52", VELVET = "#2f5d58", BLUSH = "#d8b4a6", OATMEAL = "#c9b38c";
const LEATHER = "#7a4a2c", COGNAC = "#9a5a30", BLACK_LEATHER = "#2a2523";
const RUBBER = "#1c1c1c", PLASTIC = "#e8e6e1", RED = "#b8473a", BLUE = "#3a6ea5", YELLOW = "#e0b23a", GREEN = "#3f7a4a",
  LEAF = "#4f8a55", LEAF_DARK = "#2f5e3a", POT = "#b0623a", TERRACOTTA = "#c0703f", SOIL = "#4a3626", WATER = "#6fb3cf", PINK = "#e7a6b8", MINT = "#9fd6c2";
const CAR_RED = "#8e2a2a", CAR_BLUE = "#2d4f7a", CAR_WHITE = "#e9e9e6", CAR_SILVER = "#a9adb1", CAR_BLACK = "#202224", CAR_GREEN = "#3d5a45";
const BOOKS = ["#7a3b2e", "#34405a", "#c8b27a", "#3f6b3a", "#9a5a30", "#e4dccb", "#4a4d52"];

/** How a colour is meant to look in 3D, for colours the plain guess would get wrong (a brass rail
 *  isn't wood, a yellow toy isn't pine). Read by components/plan/shapes3d.ts. */
export const LOOK_OF: Record<string, "metal" | "glass" | "mirror" | "fabric" | "leather" | "glow" | "screen" | "flame" | "plain" | "rubber" | "water"> = {
  [CHROME]: "metal", [BRASS]: "metal", [IRON]: "metal", [COPPER]: "metal", [ALU]: "metal", [STEEL]: "metal",
  [GLASS]: "glass", [MIRROR]: "mirror", [TINT]: "mirror", [SCREEN]: "screen", [GLOW]: "glow", [FLAME]: "flame", [WATER]: "water",
  [LINEN]: "fabric", [FABRIC]: "fabric", [CUSHION]: "fabric", [SAGE]: "fabric", [NAVY]: "fabric", [RUST]: "fabric", [CREAM]: "fabric",
  [CHARCOAL]: "fabric", [VELVET]: "fabric", [BLUSH]: "fabric", [OATMEAL]: "fabric",
  [LEATHER]: "leather", [COGNAC]: "leather", [BLACK_LEATHER]: "leather",
  [RUBBER]: "rubber", [PLASTIC]: "plain", [RED]: "plain", [BLUE]: "plain", [YELLOW]: "plain", [GREEN]: "plain", [PINK]: "plain", [MINT]: "plain",
  [TERRACOTTA]: "plain", [POT]: "plain", [SOIL]: "plain", [CAR_RED]: "plain", [CAR_BLUE]: "plain", [CAR_WHITE]: "plain", [CAR_SILVER]: "metal",
  [CAR_BLACK]: "plain", [CAR_GREEN]: "plain", [BOOKS[0]]: "plain", [BOOKS[2]]: "plain", [BOOKS[4]]: "plain",
};

type P = Part[];

// ---------------------------------------------------------------- builders

/** Four legs under a top of w x d, each t square and h tall, inset from the corners. */
const legs = (w: number, d: number, h: number, t: number, col: string, inset = 40): P =>
  [[-1, -1], [1, -1], [-1, 1], [1, 1]].map(([i, j]) => b(i * (w / 2 - inset), 0, j * (d / 2 - inset), t, t, h, col));
const roundLegs = (w: number, d: number, h: number, t: number, col: string, inset = 40): P =>
  [[-1, -1], [1, -1], [-1, 1], [1, 1]].map(([i, j]) => c(i * (w / 2 - inset), 0, j * (d / 2 - inset), t, t, h, col));

/** A couch: legs, a base, seat cushions, a back with its cushions, arms; an optional chaise on one side. */
function couch(w: number, d: number, h: number, col: string, o: { cush?: string; leg?: string; legH?: number; arm?: number; seat?: number; count?: number; chaise?: -1 | 1; tight?: boolean; pillows?: string } = {}): P {
  const legH = o.legH ?? 110, arm = o.arm ?? Math.min(230, w * 0.1), seat = o.seat ?? 450, cush = o.cush ?? col;
  const main = o.chaise ? Math.min(d, 980) : d, mz = -d / 2 + main / 2, back = Math.min(230, main * 0.26);
  const P: P = [];
  if (legH > 0) P.push(...roundLegs(w, main, legH, 45, o.leg ?? WALNUT, 70).map((q) => ({ ...q, z: q.z + mz })));
  P.push(b(0, legH, mz, w, main, seat - legH - 150, col));
  const count = o.count ?? (w > 1900 ? 3 : w > 1250 ? 2 : 1), sw = (w - 2 * arm) / count;
  for (let i = 0; i < count; i++) P.push(b(-w / 2 + arm + sw * (i + 0.5), seat - 150, mz + back / 2, sw - 12, main - back - 20, 150, cush));
  P.push(b(0, legH, -d / 2 + back / 2, w, back, h - legH, col));
  if (!o.tight) for (let i = 0; i < count; i++) P.push(b(-w / 2 + arm + sw * (i + 0.5), seat, -d / 2 + back + 70, sw - 16, 150, h - seat - 40, cush));
  if (arm > 0) for (const x of [-1, 1]) P.push(b(x * (w / 2 - arm / 2), legH, mz, arm, main, seat + 170 - legH, col));
  if (o.chaise) {
    const cw = Math.min(900, w * 0.36), cx = o.chaise * (w / 2 - cw / 2);
    const zFront = -d / 2 + main, len = d - main;
    P.push(b(cx, legH, zFront + len / 2, cw, len, seat - legH - 150, col), b(cx, seat - 150, zFront + len / 2 - 10, cw - 20, len, 150, cush));
  }
  if (o.pillows) for (const x of [-1, 1]) P.push(b(x * (w / 2 - arm - 200), seat, -d / 2 + back + 170, 380, 120, 380, o.pillows));
  return P;
}

/** A chair: legs, a seat, a back; arms if asked. Upholstered seat and back when uph is given. */
function chair(w: number, d: number, h: number, frame: string, o: { seat?: number; uph?: string; arms?: boolean; slats?: number; round?: boolean; backH?: number } = {}): P {
  const seat = o.seat ?? 460, t = 38, P: P = [];
  P.push(...(o.round ? roundLegs : legs)(w, d, seat - 40, t, frame, 30));
  P.push(b(0, seat - 50, 0, w, d, o.uph ? 70 : 40, o.uph ?? frame));
  for (const x of [-1, 1]) P.push(b(x * (w / 2 - 30), seat, -d / 2 + 30, t, t, h - seat, frame));
  if (o.slats) for (let i = 0; i < o.slats; i++) P.push(b(-w / 2 + 60 + ((w - 120) / (o.slats - 1 || 1)) * i, seat + 40, -d / 2 + 30, 22, 18, h - seat - 100, frame));
  if (o.uph) P.push(b(0, seat + 60, -d / 2 + 40, w - 60, 60, o.backH ?? h - seat - 80, o.uph));
  P.push(b(0, h - 70, -d / 2 + 30, w, 40, 70, frame));
  if (o.arms) for (const x of [-1, 1]) P.push(b(x * (w / 2 - 25), seat + 200, 0, 50, d - 40, 30, frame), b(x * (w / 2 - 25), seat, d / 2 - 50, 30, 30, 200, frame));
  return P;
}

/** An upholstered armchair: a couch one seat wide. */
const easy = (w: number, d: number, h: number, col: string, o: Parameters<typeof couch>[4] = {}) => couch(w, d, h, col, { count: 1, arm: Math.min(170, w * 0.2), ...o });

/** A table: a top on four legs, a pedestal or a trestle. */
function table(w: number, d: number, h: number, top: string, o: { leg?: string; round?: boolean; ped?: boolean; trestle?: boolean; t?: number; legT?: number; glass?: boolean; shelf?: boolean; apron?: boolean; inset?: number } = {}): P {
  const t = o.t ?? 35, leg = o.leg ?? top, lt = o.legT ?? 55, P: P = [];
  P.push(o.round ? c(0, h - t, 0, w, d, t, o.glass ? GLASS : top) : b(0, h - t, 0, w, d, t, o.glass ? GLASS : top));
  if (o.ped) P.push(c(0, 0, 0, w * 0.45, d * 0.45, 40, leg), c(0, 40, 0, w * 0.16, d * 0.16, h - t - 40, leg));
  else if (o.trestle) {
    for (const x of [-1, 1]) P.push(b(x * (w / 2 - 250), 0, 0, 80, d * 0.8, 60, leg), b(x * (w / 2 - 250), 60, 0, 80, 90, h - t - 60, leg));
    P.push(b(0, h * 0.3, 0, w - 500, 50, 70, leg));
  } else P.push(...(o.round ? roundLegs : legs)(w, d, h - t, lt, leg, o.inset ?? lt));
  if (o.apron && !o.round) P.push(b(0, h - t - 90, 0, w - 2 * lt, d - 2 * lt, 90, leg));
  if (o.shelf) P.push(o.round ? c(0, h * 0.25, 0, w * 0.85, d * 0.85, 20, leg) : b(0, h * 0.25, 0, w - 80, d - 80, 20, leg));
  return P;
}

type Row = ["drawer" | "door" | "glass" | "open", number, number?];
/** A case piece (dresser, cabinet, console): a body, rows of drawers or doors from the bottom up, knobs. */
function chest(w: number, d: number, h: number, col: string, rows: Row[], o: { legH?: number; front?: string; knob?: string; top?: string; plinth?: boolean } = {}): P {
  const legH = o.legH ?? 0, plinth = o.plinth ? 80 : 0, topT = 25, knob = o.knob ?? BRASS, fr = o.front ?? col, P: P = [];
  if (legH) P.push(...legs(w, d, legH, 40, col, 40));
  if (plinth) P.push(b(0, 0, -15, w - 30, d - 50, plinth, col));
  P.push(b(0, legH + plinth, -10, w, d - 20, h - legH - plinth - topT, col), b(0, h - topT, 0, w + 10, d + 10, topT, o.top ?? col));
  const avail = h - legH - plinth - topT - 20, tot = rows.reduce((a, r) => a + (r[2] ?? 1), 0);
  let y = legH + plinth + 10;
  for (const [kind, count, frac = 1] of rows) {
    const rh = (avail * frac) / tot, fw = (w - 20) / count;
    for (let i = 0; i < count; i++) {
      const x = -w / 2 + 10 + fw * (i + 0.5);
      if (kind === "open") { P.push(b(x, y + 4, d / 2 - 30, fw - 8, 4, rh - 8, INK)); continue; }
      P.push(b(x, y + 4, d / 2 - 9, fw - 6, 18, rh - 8, kind === "glass" ? GLASS : fr));
      if (kind === "glass") P.push(b(x, y + rh / 2, d / 2 - 30, fw - 40, 6, 12, fr));
      if (kind === "drawer") P.push(...(fw > 600 ? [-fw / 4, fw / 4] : [0]).map((kx) => s(x + kx, y + rh / 2 - 12, d / 2 + 6, 24, 18, 24, knob)));
      else P.push(b(x + (count === 1 ? fw / 2 - 50 : i % 2 ? -fw / 2 + 50 : fw / 2 - 50), y + rh * 0.45, d / 2 + 6, 14, 14, Math.min(140, rh * 0.3), knob));
    }
    y += rh;
  }
  return P;
}

/** Open shelves with books and boxes on them. */
function shelves(w: number, d: number, h: number, col: string, count: number, o: { back?: boolean; books?: boolean; legH?: number; ladder?: boolean } = {}): P {
  const t = 22, legH = o.legH ?? 0, P: P = [];
  for (const x of [-1, 1]) P.push(b(x * (w / 2 - t / 2), 0, 0, t, d, h, col));
  if (o.back !== false) P.push(b(0, legH, -d / 2 + 5, w, 10, h - legH, col));
  const gap = (h - legH - t) / count;
  for (let i = 0; i <= count; i++) {
    const y = legH + i * gap;
    P.push(b(0, y, 0, w - 2 * t, d - 10, t, col));
    if (o.books !== false && i < count && gap > 220) {
      const bw = (w - 2 * t) * 0.62, bh = Math.min(gap - 50, 260);
      P.push(b(-w / 2 + t + bw / 2 + 20 * (i % 2), y + t, 10, bw - 40, d * 0.75, bh, BOOKS[i % BOOKS.length]));
      if (i % 2 === 0) P.push(b(w / 2 - t - 90, y + t, 10, 120, d * 0.6, bh * 0.55, BOOKS[(i + 3) % BOOKS.length]));
    }
  }
  return P;
}

/** A bed: frame and rails, mattress, duvet, pillows, headboard; posts, a footboard or a canopy if asked. */
function bed(w: number, d: number, h: number, frame: string, o: { linen?: string; duvet?: string; legH?: number; posts?: boolean; canopy?: boolean; foot?: number; uph?: boolean; drawers?: boolean; mattress?: number; throwCol?: string } = {}): P {
  const legH = o.legH ?? 120, rail = 200, mat = o.mattress ?? 280, top = legH + rail + mat, P: P = [];
  P.push(...legs(w, d, legH, 70, frame, 40));
  P.push(b(0, legH, 20, w, d - 40, rail, frame));
  if (o.drawers) for (const x of [-1, 1]) P.push(b(x * w / 4, legH + 20, d / 2 - 10, w / 2 - 80, 20, rail - 40, frame), s(x * w / 4, legH + rail / 2, d / 2 + 6, 26, 18, 26, BRASS));
  P.push(b(0, legH + rail, 30, w - 50, d - 110, mat, o.linen ?? WHITE));
  P.push(b(0, top, 120, w - 30, d * 0.68, 60, o.duvet ?? LINEN));
  if (o.throwCol) P.push(b(0, top + 60, d / 2 - 300, w - 20, 380, 20, o.throwCol));
  const pc = w > 1300 ? 2 : 1;
  for (let i = 0; i < pc; i++) P.push(b(pc === 1 ? 0 : (i ? 1 : -1) * w / 4, top, -d / 2 + 260, w / pc - 140, 380, 150, o.linen ?? WHITE));
  P.push(b(0, 0, -d / 2 + 35, w, 70, h, o.uph ? o.duvet ?? CREAM : frame));
  if (o.foot) P.push(b(0, 0, d / 2 - 30, w, 60, o.foot, frame));
  if (o.posts || o.canopy) for (const [i, j] of [[-1, -1], [1, -1], [-1, 1], [1, 1]]) P.push(b(i * (w / 2 - 35), 0, j * (d / 2 - 35), 70, 70, o.canopy ? 2100 : h + 250, frame));
  if (o.canopy) P.push(b(0, 2060, -d / 2 + 35, w, 60, 40, frame), b(0, 2060, d / 2 - 35, w, 60, 40, frame), b(-w / 2 + 35, 2060, 0, 60, d, 40, frame), b(w / 2 - 35, 2060, 0, 60, d, 40, frame));
  return P;
}

/** A lamp on the floor or a table: base, pole, shade, the glow inside. */
function lampP(w: number, h: number, o: { base?: string; shade?: string; pole?: string; shadeH?: number; arc?: boolean; tri?: boolean; globe?: boolean } = {}): P {
  const sh = o.shadeH ?? Math.min(300, h * 0.25), base = o.base ?? BRASS, pole = o.pole ?? base, shade = o.shade ?? CREAM, P: P = [];
  if (o.tri) for (const [x, z] of [[-1, -0.6], [1, -0.6], [0, 1]]) P.push(b(x * w * 0.3, 0, z * w * 0.3, 25, 25, h - sh, pole));
  else P.push(c(0, 0, 0, w * 0.6, w * 0.6, 30, base), c(0, 30, 0, 25, 25, h - sh - 30, pole));
  if (o.arc) { P.push(b(w * 0.25, h - 80, 0, w * 0.5, 22, 22, pole), s(w * 0.45, h - sh, 0, w * 0.4, w * 0.4, sh, shade), s(w * 0.45, h - sh, 0, w * 0.2, w * 0.2, sh * 0.4, GLOW)); return P; }
  if (o.globe) P.push(s(0, h - sh, 0, w * 0.8, w * 0.8, sh, GLASS), s(0, h - sh * 0.8, 0, w * 0.3, w * 0.3, sh * 0.5, GLOW));
  else P.push(c(0, h - sh, 0, w, w, sh, shade), c(0, h - sh + 20, 0, w * 0.4, w * 0.4, sh * 0.5, GLOW));
  return P;
}

/** A screen in a thin black frame (TVs, monitors). */
const tvP = (w: number, d: number, h: number, stand = true): P => [
  b(0, stand ? 80 : 0, -d * 0.2, w, Math.min(d, 60), h - (stand ? 80 : 0), BLACK), b(0, (stand ? 80 : 0) + 15, Math.min(d, 60) / 2 - d * 0.2, w - 30, 3, h - (stand ? 80 : 0) - 30, SCREEN),
  ...(stand ? [b(0, 0, 0, w * 0.35, d, 15, IRON), b(0, 15, -d * 0.2, 80, 30, 80, IRON)] : []),
];

/** A boxy appliance: its body, a door or panel on the front, a handle, controls on top. */
function appl(w: number, d: number, h: number, col: string, o: { door?: [number, number]; glass?: boolean; handle?: "bar" | "top" | "side" | null; panel?: boolean; dial?: boolean; round?: boolean } = {}): P {
  const P: P = [b(0, 0, -10, w, d - 20, h, col)];
  const [y0, y1] = o.door ?? [h * 0.08, h * 0.85];
  if (o.round) P.push(c(0, y0, d / 2 - 10, (y1 - y0) * 0.95, 20, y1 - y0, o.glass ? GLASS : col), c(0, y0 + (y1 - y0) * 0.15, d / 2, (y1 - y0) * 0.65, 8, (y1 - y0) * 0.65, IRON));
  else P.push(b(0, y0, d / 2 - 10, w - 20, 20, y1 - y0, o.glass ? GLASS : col));
  if (o.handle === "bar" || o.handle === undefined) P.push(b(0, y1 - 60, d / 2 + 15, w * 0.6, 20, 20, CHROME));
  if (o.handle === "side") P.push(b(w / 2 - 50, y0 + (y1 - y0) * 0.3, d / 2 + 15, 20, 20, (y1 - y0) * 0.4, CHROME));
  if (o.panel !== false) P.push(b(0, y1 + 10, d / 2 - 15, w - 20, 10, Math.max(10, h - y1 - 20), BLACK));
  if (o.dial) P.push(c(w * 0.3, y1 + (h - y1) / 2 - 15, d / 2, 40, 15, 40, CHROME));
  return P;
}

/** A potted plant: pot, soil, a few balls of leaves on a stem. */
function plantP(w: number, h: number, o: { pot?: string; potH?: number; leaf?: string; tall?: boolean; tree?: boolean; spiky?: boolean } = {}): P {
  const potH = o.potH ?? Math.min(400, h * 0.3), pot = o.pot ?? TERRACOTTA, leaf = o.leaf ?? LEAF, P: P = [c(0, 0, 0, w * 0.6, w * 0.6, potH, pot), c(0, potH - 20, 0, w * 0.55, w * 0.55, 20, SOIL)];
  if (o.spiky) { for (let i = 0; i < 7; i++) { const a = (i / 7) * Math.PI * 2; P.push(b(Math.cos(a) * w * 0.12, potH, Math.sin(a) * w * 0.12, 60, 25, (h - potH) * (0.7 + (i % 3) * 0.12), i % 2 ? leaf : LEAF_DARK)); } return P; }
  if (o.tree) { P.push(c(0, potH, 0, 40, 40, (h - potH) * 0.55, WALNUT)); for (const [x, y, z, k] of [[0, 0.62, 0, 1], [-0.2, 0.75, 0.1, 0.8], [0.2, 0.8, -0.1, 0.8], [0, 0.9, 0.05, 0.7]]) P.push(s(x * w, potH + (h - potH) * y - w * 0.35 * k, z * w, w * 0.75 * k, w * 0.75 * k, w * 0.7 * k, k < 1 ? LEAF_DARK : leaf)); return P; }
  P.push(s(0, potH, 0, w, w, (h - potH) * 0.7, leaf), s(w * 0.15, potH + (h - potH) * 0.35, -w * 0.1, w * 0.7, w * 0.7, (h - potH) * 0.65, LEAF_DARK));
  return P;
}

/** A road vehicle, length along its depth: body, cabin with glass, four wheels, lights. */
function vehicle(w: number, d: number, h: number, col: string, o: { cab?: [number, number]; bed?: boolean; wheel?: number; clear?: number; boxy?: boolean } = {}): P {
  const wh = o.wheel ?? 680, clear = o.clear ?? 160, [c0, c1] = o.cab ?? [0.28, 0.8], bodyH = h * 0.42, P: P = [];
  P.push(b(0, clear, 0, w, d, bodyH, col));
  const cz0 = -d / 2 + d * c0, cz1 = -d / 2 + d * c1, ch = h - clear - bodyH;
  // the cabin in two steps, so the windshield and the back glass lean in like a real car's
  const len = cz1 - cz0, mid = (cz0 + cz1) / 2, low = ch * 0.5, cw = w - 120;
  P.push(b(0, clear + bodyH, mid, cw, len, low, col), b(0, clear + bodyH + low, mid - len * 0.04, cw - 80, len * 0.78, ch - low, col));
  P.push(b(0, clear + bodyH + 30, cz1 + 2, cw - 120, 4, low - 40, TINT), b(0, clear + bodyH + low, mid - len * 0.04 + len * 0.39 + 2, cw - 180, 4, ch - low - 50, TINT));
  P.push(b(0, clear + bodyH + 30, cz0 - 2, cw - 120, 4, low - 40, TINT));
  for (const x of [-1, 1]) P.push(b(x * (cw / 2 + 2), clear + bodyH + 40, mid, 4, len - 160, low - 60, TINT), b(x * ((cw - 80) / 2 + 2), clear + bodyH + low, mid - len * 0.04, 4, len * 0.78 - 140, ch - low - 60, TINT));
  if (!o.bed) P.push(b(0, clear + bodyH - 2, d / 2 - (d / 2 - cz1) / 2, w - 60, d / 2 - cz1 - 60, 6, col));
  if (o.bed) P.push(b(0, clear + bodyH - 20, -d / 2 + (cz0 + d / 2) / 2, w - 120, cz0 + d / 2 - 80, 30, IRON));
  for (const x of [-1, 1]) for (const z of [-1, 1]) P.push(c(x * (w / 2 - 110), 0, z * (d / 2 - d * 0.17), 230, wh, wh, RUBBER), c(x * (w / 2 - 98), wh * 0.25, z * (d / 2 - d * 0.17), 210, wh * 0.5, wh * 0.5, CHROME));
  for (const x of [-1, 1]) P.push(b(x * (w / 2 - 170), clear + bodyH - 140, d / 2 - 4, 260, 10, 80, GLOW), b(x * (w / 2 - 170), clear + bodyH - 140, -d / 2 + 4, 240, 10, 80, RED));
  P.push(b(0, clear + 40, d / 2 - 2, w - 200, 14, 130, IRON));
  return P;
}

/** A two-wheeler, length along its depth: wheels, frame, seat, handlebars, engine or none. */
function twoWheel(w: number, d: number, h: number, col: string, o: { wheel?: number; engine?: boolean; seatH?: number; tank?: boolean; deck?: boolean } = {}): P {
  const wh = o.wheel ?? 640, seat = o.seatH ?? h * 0.62, P: P = [];
  for (const z of [-1, 1]) P.push(c(0, 0, z * (d / 2 - wh / 2), 90, wh, wh, RUBBER), c(0, wh * 0.3, z * (d / 2 - wh / 2), 70, wh * 0.4, wh * 0.4, CHROME));
  if (o.deck) P.push(b(0, 120, 0, 160, d - wh, 60, col), b(0, 120, d / 2 - wh / 2 - 20, 40, 40, h - 160, ALU), b(0, h - 40, d / 2 - wh / 2 - 20, w, 30, 30, BLACK));
  else {
    P.push(b(0, wh * 0.5, 0, 60, d - wh, 70, col), b(0, wh * 0.5, -d * 0.08, 50, 50, seat - wh * 0.5, col));
    P.push(b(0, seat, -d * 0.1, 160, Math.max(260, d * 0.18), 70, BLACK), b(0, wh * 0.5, d / 2 - wh * 0.5 - 30, 50, 50, h - wh * 0.5 - 60, CHROME), b(0, h - 50, d / 2 - wh * 0.5 - 40, w, 30, 30, BLACK));
    if (o.engine) P.push(b(0, wh * 0.25, 0, 300, d * 0.22, wh * 0.45, IRON), b(0, wh * 0.25, -d * 0.2, 90, d * 0.3, 90, CHROME));
    if (o.tank) P.push(b(0, seat - 40, d * 0.07, 280, d * 0.18, 200, col));
  }
  return P;
}

/** A plate, bowl or stack of them. */
const disc = (w: number, h: number, col: string, count = 1, step = 0): P => Array.from({ length: count }, (_, i) => c(0, i * step, 0, w, w, h, col));

/** Something on a frame of four posts with a roof (gazebo, pergola, carport). */
function postsRoof(w: number, d: number, h: number, col: string, roof: string | null, o: { slats?: number } = {}): P {
  const P: P = legs(w, d, h - 150, 120, col, 80);
  P.push(b(0, h - 150, -d / 2 + 80, w, 80, 150, col), b(0, h - 150, d / 2 - 80, w, 80, 150, col), b(-w / 2 + 80, h - 150, 0, 80, d, 150, col), b(w / 2 - 80, h - 150, 0, 80, d, 150, col));
  if (roof) P.push(b(0, h - 20, 0, w + 200, d + 200, 40, roof));
  if (o.slats) for (let i = 0; i < o.slats; i++) P.push(b(0, h, -d / 2 + (d / (o.slats - 1)) * i, w + 150, 50, 120, col));
  return P;
}

