type Opt = Partial<ObjectSpec>;
const H: Record<string, ObjectSpec> = {};
/** One kind: its label, size [w, d, h] in mm, weight, top-view colour, its look and the rest. */
function K(kind: string, label: string, [w, d, h]: number[], kg: number, fill: string, look: ((w: number, d: number, h: number) => P) | string, o: Opt = {}) {
  H[kind] = { label, w, d, h, kg, mount: "floor", face: "room", fill, ...(typeof look === "string" ? { like: look } : { parts: look(w, d, h) }), ...o };
}
const ON_COUNTER: Opt = { mount: "surface", on: ["base_cabinet", "island", "kitchen_sink", "kitchen_cart", "sideboard", "table"], back: true, face: "with" };
const ON_TABLE: Opt = { mount: "surface", on: ["dining_table", "table", "round_dining_table", "island", "coffee_table", "kitchen_cart", "sideboard"], face: "any" };
const ON_DESK: Opt = { mount: "surface", on: ["desk", "standing_desk", "corner_desk", "executive_desk", "writing_desk", "table"], back: true, face: "with" };
const ON_SHELF: Opt = { mount: "surface", on: ["sideboard", "console_table", "bookshelf", "dresser", "nightstand", "tv_stand", "media_console", "side_table"], face: "with" };
const WALL = (at: number): Opt => ({ mount: "wall", at, face: "room" });
const CEIL = (at: number): Opt => ({ mount: "ceiling", at, face: "any" });
const ANY: Opt = { face: "any" };
const SIT = (...to: string[]): Opt => ({ face: "to", to });
const W = (...words: string[]): Opt => ({ words });

